// Change permissions in current directory (like chmod)
fchmodat(AT_FDCWD, "file.log", 0640, 0);

// Set up directory context
int dfd = open("temp_dir", O_RDONLY | O_DIRECTORY);

// Change permissions relative to dfd (standard behavior)
fchmodat(dfd, "private_data", S_IRWXU, 0); // 0700

// Use flag: If "link" is a symlink, change permissions
// of the link itself, not the target file.
fchmodat(dfd, "link", 0400, AT_SYMLINK_NOFOLLOW);

close(dfd);
